 "/seed-of-the-day/":()=>!!document.querySelector("#sheet svg")&&quiet("status"),
};
const settled=()=>(settledOf[location.pathname]??(()=>true))()&&document.fonts.status==="loaded";
await until("settled",settled);
{const how=document.querySelector('.lf-station[data-station="how"]');const pip=how.cloneNode(true);pip.dataset.station="primer";pip.dataset.nx="0.8244666666666667";pip.dataset.ny="0.6765780314872228";
